// routes.cpp
// Every /api/... endpoint. Each one:
//   1. reads its inputs from the URL,
//   2. calls resetTrace() and then ONE student module function,
//   3. replies with JSON holding the result, the cost (checks, moves) and the step trace.
// The full list of endpoints and their JSON shapes is in docs/api.md.
// Teacher-provided server code: students do not edit this file.

#include "routes.h"
#include "httplib.h"
#include "app_state.h"
#include "json_out.h"

#include "config.h"
#include "step_trace.h"
#include "seat_row.h"
#include "waitlist.h"
#include "search.h"
#include "sorting.h"
#include "merging.h"
#include "hall.h"
#include "customer_names.h"
#include "complexity.h"

#include <cstdlib>
#include <cstring>
#include <ctime>
#include <fstream>
#include <mutex>
#include <random>
#include <sstream>
#include <string>

#ifndef SOURCE_DIR
#define SOURCE_DIR "src"                // folder whose .cpp files the code viewer shows
#endif

#ifndef SERVER_MODE
#define SERVER_MODE "solution"          // "solution" (src/) or "starter" (starter/src/)
#endif

namespace
{
    AppState state;                     // the whole cinema
    std::mutex stateLock;               // one request changes the cinema at a time
    std::mt19937 randomEngine((unsigned)std::time(nullptr));    // for shuffling bookings

    // ---------- small helpers ----------

    void sendJson(httplib::Response& res, const std::string& body, int status = 200)
    {
        res.status = status;
        res.set_header("Cache-Control", "no-store");
        res.set_content(body, "application/json; charset=utf-8");
    }

    void sendError(httplib::Response& res, const std::string& message, int status = 400)
    {
        sendJson(res, "{\"ok\":false,\"message\":" + jsonText(message) + "}", status);
    }

    // Reads an integer parameter. Returns false (and replies with an error) if missing or not a number.
    bool readInt(const httplib::Request& req, httplib::Response& res, const char* name, int& value)
    {
        if (!req.has_param(name))
        {
            sendError(res, std::string("Missing parameter: ") + name);
            return false;
        }
        std::string text = req.get_param_value(name);
        char* end = nullptr;
        long parsed = std::strtol(text.c_str(), &end, 10);
        if (text.empty() || *end != '\0' || parsed < -1000000000L || parsed > 1000000000L)
        {
            sendError(res, std::string("Parameter is not a whole number: ") + name);
            return false;
        }
        value = (int)parsed;
        return true;
    }

    // Reads an optional integer parameter, using fallback when it is absent.
    bool readIntOr(const httplib::Request& req, httplib::Response& res, const char* name, int fallback, int& value)
    {
        if (!req.has_param(name))
        {
            value = fallback;
            return true;
        }
        return readInt(req, res, name, value);
    }

    // Parses "1047,1003,1029" into list. Returns how many values, or -1 if the text is invalid or too long.
    int parseList(const std::string& text, int list[], int capacity)
    {
        int count = 0;
        std::stringstream stream(text);
        std::string piece;
        while (std::getline(stream, piece, ','))
        {
            if (piece.empty())
            {
                continue;
            }
            char* end = nullptr;
            long parsed = std::strtol(piece.c_str(), &end, 10);
            if (*end != '\0' || parsed < -1000000 || parsed > 1000000)
            {
                return -1;
            }
            if (count == capacity)
            {
                return -1;
            }
            list[count] = (int)parsed;
            count = count + 1;
        }
        return count;
    }

    std::string stateJson()             // the whole cinema as one JSON object
    {
        return "{\"row\":" + jsonInts(state.row, ROW_SIZE)
             + ",\"waitlist\":" + jsonInts(state.waitlist, state.waitCount)
             + ",\"waitCapacity\":" + std::to_string(MAX_WAIT)
             + ",\"bookings\":" + jsonInts(state.bookings, state.bookingCount)
             + ",\"sorted\":" + jsonInts(state.sorted, state.sortedCount)
             + ",\"online\":" + jsonInts(state.online, state.onlineCount)
             + ",\"counter\":" + jsonInts(state.counter, state.counterCount)
             + ",\"hall\":" + jsonHall(state.hall, ROWS)
             + ",\"names\":" + jsonNames(state.names, state.nameCount)
             + ",\"nameCapacity\":" + std::to_string(MAX_CUSTOMERS)
             + ",\"nameLength\":" + std::to_string(NAME_LEN)
             + ",\"sizeofInt\":" + std::to_string((int)sizeof(int))
             + ",\"mode\":" + jsonText(SERVER_MODE)
             + "}";
    }

    // Standard reply for an action: ok flag, message, result value, cost, trace, extra fields, and full state.
    std::string actionJson(bool ok, const std::string& message, const std::string& extra)
    {
        std::string body = "{\"ok\":" + jsonBool(ok) + ",\"message\":" + jsonText(message) + "," + jsonCost();
        if (!extra.empty())
        {
            body += "," + extra;
        }
        body += ",\"state\":" + stateJson() + "}";
        return body;
    }

    bool isAllowedSource(const std::string& name)
    {
        const char* allowed[] = {"seat_row", "waitlist", "search", "sorting", "merging",
                                 "hall", "customer_names", "complexity"};
        for (const char* item : allowed)
        {
            if (name == item)
            {
                return true;
            }
        }
        return false;
    }

    // Runs one named sort on list. Returns false if the name is unknown.
    bool runSort(const std::string& algorithm, int list[], int count)
    {
        if (algorithm == "bubble")
        {
            bubbleSort(list, count);
            return true;
        }
        if (algorithm == "selection")
        {
            selectionSort(list, count);
            return true;
        }
        if (algorithm == "insertion")
        {
            insertionSort(list, count);
            return true;
        }
        return false;
    }
}

void registerRoutes(httplib::Server& server)
{
    resetState(state);

    // ---------- general ----------

    server.Get("/api/info", [](const httplib::Request&, httplib::Response& res)
    {
        sendJson(res, "{\"ok\":true,\"mode\":" + jsonText(SERVER_MODE)
                    + ",\"sourceDir\":" + jsonText(SOURCE_DIR)
                    + ",\"sizeofInt\":" + std::to_string((int)sizeof(int)) + "}");
    });

    server.Get("/api/state", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        sendJson(res, "{\"ok\":true,\"state\":" + stateJson() + "}");
    });

    server.Post("/api/reset", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        resetState(state);
        sendJson(res, actionJson(true, "Opening-night data restored", ""));
    });

    server.Get("/api/source", [](const httplib::Request& req, httplib::Response& res)
    {
        std::string name = req.get_param_value("module");
        if (!isAllowedSource(name))
        {
            sendError(res, "Unknown module");
            return;
        }
        std::string path = std::string(SOURCE_DIR) + "/" + name + ".cpp";
        std::ifstream file(path, std::ios::binary);
        if (!file)
        {
            sendError(res, "Cannot open " + path + " (start the server from the project folder)", 404);
            return;
        }
        std::stringstream buffer;
        buffer << file.rdbuf();
        sendJson(res, "{\"ok\":true,\"path\":" + jsonText(path) + ",\"code\":" + jsonText(buffer.str()) + "}");
    });

    // ---------- Stage 2: one row ----------

    server.Post("/api/row/book", [](const httplib::Request& req, httplib::Response& res)
    {
        int seat = 0;
        if (!readInt(req, res, "seat", seat))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        bool ok = bookSeat(state.row, ROW_SIZE, seat);
        std::string message = ok ? "Seat " + std::to_string(seat) + " booked"
                                 : "Seat " + std::to_string(seat) + " is not available";
        sendJson(res, actionJson(ok, message, "\"seat\":" + std::to_string(seat)));
    });

    server.Post("/api/row/cancel", [](const httplib::Request& req, httplib::Response& res)
    {
        int seat = 0;
        if (!readInt(req, res, "seat", seat))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        bool ok = cancelSeat(state.row, ROW_SIZE, seat);
        std::string message = ok ? "Seat " + std::to_string(seat) + " cancelled"
                                 : "Seat " + std::to_string(seat) + " was not booked";
        sendJson(res, actionJson(ok, message, "\"seat\":" + std::to_string(seat)));
    });

    server.Get("/api/row/count-free", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int freeSeats = countFreeSeats(state.row, ROW_SIZE);
        sendJson(res, actionJson(true, std::to_string(freeSeats) + " free seats",
                                 "\"result\":" + std::to_string(freeSeats)));
    });

    server.Get("/api/row/address", [](const httplib::Request& req, httplib::Response& res)
    {
        int index = 0;
        int base = 0;
        int width = 0;
        int lowerBound = 0;
        if (!readInt(req, res, "index", index) || !readIntOr(req, res, "base", 1000, base)
            || !readIntOr(req, res, "width", (int)sizeof(int), width) || !readIntOr(req, res, "lb", 0, lowerBound))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        int formula = addressOf1D(base, width, index, lowerBound);
        std::string real = "null";
        bool realMatches = false;
        if (index >= 0 && index < ROW_SIZE)     // a real C++ check is possible for real seats
        {
            long long gap = (long long)((const char*)&state.row[index] - (const char*)&state.row[0]);
            real = std::to_string(gap);
            realMatches = (gap == (long long)sizeof(int) * index);
        }
        sendJson(res, "{\"ok\":true,\"formula\":" + std::to_string(formula)
                    + ",\"realOffsetBytes\":" + real
                    + ",\"realMatchesFormula\":" + jsonBool(realMatches)
                    + ",\"sizeofInt\":" + std::to_string((int)sizeof(int)) + "}");
    });

    // ---------- Stage 3: waitlist ----------

    server.Post("/api/waitlist/insert", [](const httplib::Request& req, httplib::Response& res)
    {
        int position = 0;
        int value = 0;
        if (!readInt(req, res, "position", position) || !readInt(req, res, "value", value))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        std::string before = jsonInts(state.waitlist, state.waitCount);
        resetTrace();
        int oldCount = state.waitCount;
        state.waitCount = insertAt(state.waitlist, state.waitCount, MAX_WAIT, position, value);
        bool ok = state.waitCount == oldCount + 1;
        std::string message;
        if (ok)
        {
            message = std::to_string(value) + " joined at position " + std::to_string(position);
        }
        else if (oldCount == MAX_WAIT)
        {
            message = "Waitlist full";
        }
        else if (position >= 0 && position <= oldCount)
        {
            message = "insertAt did not add anyone at a valid position (is the function finished?)";
        }
        else
        {
            message = "Invalid position " + std::to_string(position) + " (allowed 0 to " + std::to_string(oldCount) + ")";
        }
        sendJson(res, actionJson(ok, message, "\"before\":" + before));
    });

    server.Post("/api/waitlist/delete", [](const httplib::Request& req, httplib::Response& res)
    {
        int position = 0;
        if (!readInt(req, res, "position", position))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        std::string before = jsonInts(state.waitlist, state.waitCount);
        resetTrace();
        int oldCount = state.waitCount;
        state.waitCount = deleteAt(state.waitlist, state.waitCount, position);
        bool ok = state.waitCount == oldCount - 1;
        std::string message;
        if (ok)
        {
            message = "Position " + std::to_string(position) + " left the waitlist";
        }
        else if (position >= 0 && position < oldCount)
        {
            message = "deleteAt did not remove anyone from a valid position (is the function finished?)";
        }
        else
        {
            message = "Invalid position " + std::to_string(position);
        }
        sendJson(res, actionJson(ok, message, "\"before\":" + before));
    });

    // ---------- Stage 4 and 6: searching ----------

    server.Get("/api/search/free-seat", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int found = findFreeSeat(state.row, ROW_SIZE);
        std::string message = found >= 0 ? "First free seat is " + std::to_string(found) : "House full";
        sendJson(res, actionJson(found >= 0, message, "\"result\":" + std::to_string(found)));
    });

    server.Get("/api/search/linear", [](const httplib::Request& req, httplib::Response& res)
    {
        int key = 0;
        if (!readInt(req, res, "key", key))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int found = linearSearch(state.bookings, state.bookingCount, key);
        std::string message = found >= 0 ? std::to_string(key) + " found at index " + std::to_string(found)
                                         : std::to_string(key) + " not found";
        sendJson(res, actionJson(found >= 0, message, "\"result\":" + std::to_string(found)
                                 + ",\"list\":" + jsonInts(state.bookings, state.bookingCount)));
    });

    server.Get("/api/search/binary", [](const httplib::Request& req, httplib::Response& res)
    {
        int key = 0;
        if (!readInt(req, res, "key", key))
        {
            return;
        }
        std::string which = req.has_param("list") ? req.get_param_value("list") : "sorted";
        std::lock_guard<std::mutex> guard(stateLock);
        int* list = state.sorted;
        int count = state.sortedCount;
        if (which == "unsorted")        // deliberate mistake demo: binary search on unsorted data
        {
            list = state.bookings;
            count = state.bookingCount;
        }
        else if (count == 0)
        {
            sendError(res, "Sort the bookings first (Stage 5), or pass list=unsorted to see what goes wrong", 409);
            return;
        }
        resetTrace();
        int found = binarySearch(list, count, key);
        std::string message = found >= 0 ? std::to_string(key) + " found at index " + std::to_string(found)
                                         : std::to_string(key) + " not found";
        sendJson(res, actionJson(found >= 0, message, "\"result\":" + std::to_string(found)
                                 + ",\"list\":" + jsonInts(list, count)
                                 + ",\"listName\":" + jsonText(which == "unsorted" ? "unsorted" : "sorted")));
    });

    // ---------- Stage 5: sorting ----------

    server.Post("/api/bookings/shuffle", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        for (int i = state.bookingCount - 1; i > 0; i--)
        {
            std::uniform_int_distribution<int> pick(0, i);
            int j = pick(randomEngine);
            int temp = state.bookings[i];
            state.bookings[i] = state.bookings[j];
            state.bookings[j] = temp;
        }
        state.sortedCount = 0;
        resetTrace();
        sendJson(res, actionJson(true, "Bookings shuffled", ""));
    });

    server.Post("/api/bookings/set", [](const httplib::Request& req, httplib::Response& res)
    {
        int values[MAX_BOOKINGS];
        int count = parseList(req.get_param_value("values"), values, MAX_BOOKINGS);
        if (count < 2)
        {
            sendError(res, "Give 2 to " + std::to_string(MAX_BOOKINGS) + " whole numbers separated by commas");
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        copyList(values, state.bookings, count);
        state.bookingCount = count;
        state.sortedCount = 0;
        resetTrace();
        sendJson(res, actionJson(true, "Bookings replaced", ""));
    });

    server.Post("/api/sort", [](const httplib::Request& req, httplib::Response& res)
    {
        std::string algorithm = req.get_param_value("algorithm");
        std::lock_guard<std::mutex> guard(stateLock);
        int work[MAX_BOOKINGS];
        copyList(state.bookings, work, state.bookingCount);
        resetTrace();
        if (!runSort(algorithm, work, state.bookingCount))
        {
            sendError(res, "algorithm must be bubble, selection or insertion");
            return;
        }
        bool sortedOk = isSorted(work, state.bookingCount);
        std::string cost = jsonCost();          // read the cost before anything else can change it
        copyList(work, state.sorted, state.bookingCount);
        state.sortedCount = sortedOk ? state.bookingCount : 0;
        std::string message = sortedOk ? algorithm + " sort finished" : algorithm + " sort did not produce a sorted list";
        std::string body = "{\"ok\":" + jsonBool(sortedOk) + ",\"message\":" + jsonText(message) + "," + cost
                         + ",\"algorithm\":" + jsonText(algorithm)
                         + ",\"before\":" + jsonInts(state.bookings, state.bookingCount)
                         + ",\"after\":" + jsonInts(work, state.bookingCount)
                         + ",\"state\":" + stateJson() + "}";
        sendJson(res, body);
    });

    // Best, worst and random-order cost of all three sorts for one size n (Stage 5 table, Stage 10).
    server.Get("/api/sort/compare", [](const httplib::Request& req, httplib::Response& res)
    {
        int n = 0;
        if (!readIntOr(req, res, "n", 50, n))
        {
            return;
        }
        if (n < 2 || n > 300)
        {
            sendError(res, "n must be between 2 and 300");
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        static int original[300];
        static int work[300];
        const char* algorithms[] = {"bubble", "selection", "insertion"};
        const char* orders[] = {"sorted", "random", "reversed"};
        std::string rows = "[";
        bool first = true;
        for (const char* order : orders)
        {
            for (int i = 0; i < n; i++)
            {
                original[i] = i;
            }
            if (std::string(order) == "reversed")
            {
                for (int i = 0; i < n; i++)
                {
                    original[i] = n - 1 - i;
                }
            }
            else if (std::string(order) == "random")
            {
                std::mt19937 fixedEngine(205);  // same "random" list every time, so results are repeatable
                for (int i = n - 1; i > 0; i--)
                {
                    std::uniform_int_distribution<int> pick(0, i);
                    int j = pick(fixedEngine);
                    int temp = original[i];
                    original[i] = original[j];
                    original[j] = temp;
                }
            }
            for (const char* algorithm : algorithms)
            {
                copyList(original, work, n);
                resetTrace();
                runSort(algorithm, work, n);
                if (!first)
                {
                    rows += ",";
                }
                first = false;
                rows += "{\"algorithm\":" + jsonText(algorithm) + ",\"order\":" + jsonText(order)
                      + ",\"checks\":" + std::to_string(checkCount())
                      + ",\"moves\":" + std::to_string(moveCount())
                      + ",\"sortedOk\":" + jsonBool(isSorted(work, n)) + "}";
            }
        }
        rows += "]";
        resetTrace();
        sendJson(res, "{\"ok\":true,\"n\":" + std::to_string(n) + ",\"rows\":" + rows + "}");
    });

    // ---------- Stage 7: merging ----------

    server.Get("/api/merge", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        int result[2 * MAX_BOOKINGS];
        resetTrace();
        int total = mergeSorted(state.online, state.onlineCount, state.counter, state.counterCount, result);
        bool ok = isSorted(result, total) && total == state.onlineCount + state.counterCount;
        std::string message = ok ? "Merged " + std::to_string(total) + " bookings" : "Merge result is wrong";
        sendJson(res, actionJson(ok, message, "\"result\":" + jsonInts(result, total)));
    });

    server.Post("/api/merge/set", [](const httplib::Request& req, httplib::Response& res)
    {
        int first[MAX_BOOKINGS];
        int second[MAX_BOOKINGS];
        int firstCount = parseList(req.get_param_value("online"), first, MAX_BOOKINGS);
        int secondCount = parseList(req.get_param_value("counter"), second, MAX_BOOKINGS);
        if (firstCount < 0 || secondCount < 0 || firstCount + secondCount == 0)
        {
            sendError(res, "Give up to " + std::to_string(MAX_BOOKINGS) + " numbers per list, separated by commas");
            return;
        }
        if (!isSorted(first, firstCount) || !isSorted(second, secondCount))
        {
            sendError(res, "Both lists must already be sorted ascending: merging needs sorted input");
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        copyList(first, state.online, firstCount);
        copyList(second, state.counter, secondCount);
        state.onlineCount = firstCount;
        state.counterCount = secondCount;
        resetTrace();
        sendJson(res, actionJson(true, "Lists replaced", ""));
    });

    // ---------- Stage 8: full hall ----------

    server.Post("/api/hall/book", [](const httplib::Request& req, httplib::Response& res)
    {
        int row = 0;
        int col = 0;
        if (!readInt(req, res, "row", row) || !readInt(req, res, "col", col))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        bool ok = bookHallSeat(state.hall, row, col);
        std::string seatName = "[" + std::to_string(row) + "][" + std::to_string(col) + "]";
        sendJson(res, actionJson(ok, ok ? "Seat " + seatName + " booked" : "Seat " + seatName + " is not available", ""));
    });

    server.Post("/api/hall/cancel", [](const httplib::Request& req, httplib::Response& res)
    {
        int row = 0;
        int col = 0;
        if (!readInt(req, res, "row", row) || !readInt(req, res, "col", col))
        {
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        bool ok = cancelHallSeat(state.hall, row, col);
        std::string seatName = "[" + std::to_string(row) + "][" + std::to_string(col) + "]";
        sendJson(res, actionJson(ok, ok ? "Seat " + seatName + " cancelled" : "Seat " + seatName + " was not booked", ""));
    });

    server.Get("/api/hall/count", [](const httplib::Request&, httplib::Response& res)
    {
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int booked = countBooked(state.hall);
        sendJson(res, actionJson(true, std::to_string(booked) + " seats booked", "\"result\":" + std::to_string(booked)));
    });

    server.Get("/api/hall/address", [](const httplib::Request& req, httplib::Response& res)
    {
        int row = 0;
        int col = 0;
        int base = 0;
        int width = 0;
        int lowRow = 0;
        int lowCol = 0;
        int rows = 0;
        int cols = 0;
        if (!readInt(req, res, "row", row) || !readInt(req, res, "col", col)
            || !readIntOr(req, res, "base", 2000, base) || !readIntOr(req, res, "width", (int)sizeof(int), width)
            || !readIntOr(req, res, "lr", 0, lowRow) || !readIntOr(req, res, "lc", 0, lowCol)
            || !readIntOr(req, res, "rows", ROWS, rows) || !readIntOr(req, res, "cols", COLS, cols))
        {
            return;
        }
        int rowMajor = rowMajorAddress(base, width, row, col, lowRow, lowCol, cols);
        int columnMajor = columnMajorAddress(base, width, row, col, lowRow, lowCol, rows);
        std::string real = "null";
        bool realMatches = false;
        std::lock_guard<std::mutex> guard(stateLock);
        // A real C++ check is only meaningful for the actual hall: 0-based, ROWS x COLS, int-sized boxes.
        if (lowRow == 0 && lowCol == 0 && rows == ROWS && cols == COLS && row >= 0 && row < ROWS && col >= 0 && col < COLS)
        {
            long long gap = (long long)((const char*)&state.hall[row][col] - (const char*)&state.hall[0][0]);
            real = std::to_string(gap);
            realMatches = (gap == (long long)sizeof(int) * (row * COLS + col));
        }
        sendJson(res, "{\"ok\":true,\"rowMajor\":" + std::to_string(rowMajor)
                    + ",\"columnMajor\":" + std::to_string(columnMajor)
                    + ",\"realOffsetBytes\":" + real
                    + ",\"realMatchesRowMajor\":" + jsonBool(realMatches)
                    + ",\"sizeofInt\":" + std::to_string((int)sizeof(int)) + "}");
    });

    // ---------- Stage 9: customer names ----------

    server.Post("/api/names/add", [](const httplib::Request& req, httplib::Response& res)
    {
        std::string name = req.get_param_value("name");
        if (name.size() >= 200)
        {
            sendError(res, "Name too long");
            return;
        }
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int oldCount = state.nameCount;
        state.nameCount = addCustomer(state.names, state.nameCount, MAX_CUSTOMERS, name.c_str());
        bool ok = state.nameCount == oldCount + 1;
        std::string message;
        if (ok)
        {
            message = name + " added";
        }
        else if (oldCount == MAX_CUSTOMERS)
        {
            message = "Name list full";
        }
        else
        {
            message = "Name must have 1 to " + std::to_string(NAME_LEN - 1) + " letters";
        }
        sendJson(res, actionJson(ok, message, ""));
    });

    server.Get("/api/names/find", [](const httplib::Request& req, httplib::Response& res)
    {
        std::string name = req.get_param_value("name");
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int found = findCustomer(state.names, state.nameCount, name.c_str());
        std::string message = found >= 0 ? name + " found at index " + std::to_string(found) : name + " not found";
        sendJson(res, actionJson(found >= 0, message, "\"result\":" + std::to_string(found)));
    });

    server.Get("/api/names/inspect", [](const httplib::Request& req, httplib::Response& res)
    {
        std::string name = req.get_param_value("name");
        if (name.size() >= 200)
        {
            sendError(res, "Name too long");
            return;
        }
        char buffer[200];
        std::strcpy(buffer, name.c_str());
        std::lock_guard<std::mutex> guard(stateLock);
        resetTrace();
        int length = myLength(buffer);
        std::string cost = jsonCost();
        toUpperCase(buffer);
        std::string codes = "[";
        for (size_t i = 0; i <= name.size(); i++)   // include the '\0' end marker
        {
            if (i > 0)
            {
                codes += ",";
            }
            codes += std::to_string((int)(unsigned char)name[i]);
        }
        codes += "]";
        sendJson(res, "{\"ok\":true,\"message\":" + jsonText(name + " has " + std::to_string(length) + " letters") + ","
                    + cost + ",\"length\":" + std::to_string(length)
                    + ",\"upper\":" + jsonText(buffer) + ",\"asciiCodes\":" + codes + "}");
    });

    // ---------- Stage 10: complexity ----------

    server.Get("/api/complexity", [](const httplib::Request& req, httplib::Response& res)
    {
        int sizes[8];
        std::string text = req.has_param("sizes") ? req.get_param_value("sizes") : "10,100,1000";
        int count = parseList(text, sizes, 8);
        if (count <= 0)
        {
            sendError(res, "sizes must be up to 8 numbers, for example 10,100,1000");
            return;
        }
        for (int i = 0; i < count; i++)
        {
            if (sizes[i] < 1 || sizes[i] > BIG)
            {
                sendError(res, "each size must be between 1 and " + std::to_string(BIG));
                return;
            }
        }
        std::lock_guard<std::mutex> guard(stateLock);
        static int big[BIG];
        fillSequence(big, BIG);
        std::string rows = "[";
        for (int i = 0; i < count; i++)
        {
            int n = sizes[i];
            int linear = worstLinearChecks(big, n);
            int binary = worstBinaryChecks(big, n);
            if (i > 0)
            {
                rows += ",";
            }
            rows += "{\"n\":" + std::to_string(n) + ",\"linear\":" + std::to_string(linear)
                  + ",\"binary\":" + std::to_string(binary)
                  + ",\"maxBinary\":" + std::to_string(maxBinaryChecks(n)) + "}";
        }
        rows += "]";
        resetTrace();
        sendJson(res, "{\"ok\":true,\"rows\":" + rows + "}");
    });
}
